import itertools

class Solution:
    def flipgame(self, fronts: List[int], backs: List[int]) -> int:
        same = {n for i, n in enumerate(fronts) if n == backs[i]}
        result = float("inf")
        for n in itertools.chain(fronts, backs):
            if n not in same:
                result = min(result, n)
        return result if result < float("inf") else 0

