class Solution:
    def numFactoredBinaryTrees(self, nums: List[int]) -> int:
        nums = set(nums)
        n = len(nums)

        @lru_cache(None)
        def helper(num):
            trees = 1
            for factor in nums:
                if not num % factor and num // factor in nums:
                    trees += helper(factor) * helper(num // factor)

            return trees

        return sum(helper(num) for num in nums) % (10 ** 9 + 7)

class Solution:
    def numFactoredBinaryTrees(self, A):
        M = 10**9 + 7
        A.sort()
        dp = {}
        for i in range(len(A)):
            dp[A[i]] = 1
            for j in range(i):
                if A[i] % A[j] == 0 and A[i] // A[j] in dp:
                    dp[A[i]] += dp[A[j]] * dp[A[i] // A[j]]
                    dp[A[i]] %= M
        return sum(dp.values()) % M

class Solution:
    def toGoatLatin(self, sentence: str) -> str:
        wordList, result, index = sentence.split(' '), "", 1
        for word in wordList:
            if index > 1:
                result += " "
            firstLetter = word[0]
            if firstLetter in 'aeiouAEIOU':
                result += word + "ma"
            else:
                result += word[1:] + firstLetter + "ma"
            for i in range(index):
                result += 'a'
            index += 1
        return result

class Solution:
    def toGoatLatin(self, S):
        def convert(S):
            vowel = set('aeiouAEIOU')
            for i, word in enumerate(S.split(), 1):
                if word[0] not in vowel:
                    word = word[1:] + word[:1]
                yield word + 'ma' + 'a'*i
        return " ".join(convert(S))

