class Solution:
    def largeGroupPositions(self, s: str) -> List[List[int]]:

        i=0
        c=1
        prev=""
        l=len(s)
        ans=[]
        while i<l:
            if s[i]==prev:
                c+=1
                if (i==l-1) & (c>=3):
                    ans.append([i+1-c,i])
            else:
                if c>=3:
                    ans.append([i-c,i-1])
                c=1
            prev=s[i]
            i+=1
        return ans

class Solution:
    def largeGroupPositions(self, S):
        result = []
        i = 0
        for j in range(len(S)):
            if j == len(S)-1 or S[j] != S[j+1]:
                if j-i+1 >= 3:
                    result.append([i, j])
                i = j+1
        return result

